const STORAGE='rules-city-level1-final-v1',fresh={socialControlCompleted:false,keyTaken:false,lockerOpened:false,seatPlanCompleted:false,socialNormsCompleted:false,genderNormCompleted:false,checkoutCompleted:false,panX:0};let state=load(),selectedCard,selectedName,placed={},selectedGender=new Set(),assignmentPlaced={},selectedAssignment;const $=s=>document.querySelector(s),app=$('#app'),answer={A:'子晴',B:'宥辰',C:'柏翰',D:'品妤'},seats=Object.keys(answer);
function load(){try{return{...fresh,...JSON.parse(localStorage.getItem(STORAGE))}}catch{return{...fresh}}}function save(){localStorage.setItem(STORAGE,JSON.stringify(state))}function keepPan(){let p=$('#pan');if(p){state.panX=p.scrollLeft;save()}}function scene(){keepPan();renderScene()}function shuffle(a){return[...a].sort(()=>Math.random()-.5)}function esc(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(t){let e=document.createElement('div');e.className='toast';e.textContent=t;app.append(e);setTimeout(()=>e.remove(),2700)}
function start(){localStorage.getItem(STORAGE)?title():renderScene(true)}function title(){app.innerHTML=`<section class="start"><div class="start-card"><p>《規則之城》</p><h1>壹<br>放學後的203</h1><button class="btn light" onclick="renderScene()">繼續第一關</button><p><button class="mini" onclick="restartAsk()">重新開始第一關</button></p></div></section>`}function anchor(id,label){return`<span class="task-hint anchor-${id}" data-hint="${id}"><i></i>${label}</span>`}
function renderScene(first=false){let keyVisible=state.socialControlCompleted&&!state.keyTaken;app.innerHTML=`<section class="scene"><div class="pan" id="pan" onscroll="onPan()"><div class="world ${state.lockerOpened?'locker-open':''} ${keyVisible?'key-visible':''}"><button class="world-hit journal-hit" onclick="journal()" aria-label="講桌上的綠色班級日誌"></button>${(!state.socialControlCompleted||state.seatPlanCompleted||state.genderNormCompleted)&&!state.checkoutCompleted?anchor('journal','班級日誌'):''}${keyVisible?`<button class="world-hit key-hit" onclick="takeKey()" aria-label="講桌上的金屬鑰匙"></button><button class="task-hint anchor-key" data-hint="key" onclick="takeKey()"><i></i>鑰匙</button>`:''}<button class="world-hit desk-hit" onclick="toast('講桌上放著班級日誌。')" aria-label="講桌"></button>${!state.lockerOpened?`<button class="world-hit locker-hit" onclick="openLocker()" aria-label="置物櫃"></button>${state.keyTaken?anchor('locker','置物櫃'):''}`:`<button class="world-hit seat-plan-hit" onclick="seatGame()" aria-label="置物櫃內的203座位表"></button>${!state.seatPlanCompleted?anchor('seat','203座位表'):''}`}<button class="world-hit board-hit" onclick="bulletin()" aria-label="班級公告欄"></button>${state.socialNormsCompleted&&!state.genderNormCompleted?anchor('bulletin','公告欄'):''}<button class="world-hit door-hit" onclick="door()" aria-label="教室門"></button></div></div><header class="topbar"><div class="mission"><b>17:10</b><br>離開前，完成203最後的確認</div><div class="top-actions"><button class="mini" onclick="hint()">提示</button><button class="mini" onclick="menu()">選單</button></div></header><nav class="pan-nav"><button onclick="panTo('left')">〈 教室左側</button><button onclick="panTo('right')">教室右側 〉</button></nav><div class="bag">${bag()}</div></section>`;let p=$('#pan');p.scrollLeft=state.panX||0;setTimeout(showHints,300);if(first)setTimeout(()=>toast('壹　放學後的203'),300)}function onPan(){keepPan();document.querySelectorAll('.task-hint.visible').forEach(x=>x.classList.remove('visible'));clearTimeout(window.hintTimer);window.hintTimer=setTimeout(showHints,300)}function showHints(){document.querySelectorAll('.task-hint').forEach(h=>{let r=h.getBoundingClientRect(),a=Math.max(0,Math.min(r.right,innerWidth)-Math.max(r.left,0))*Math.max(0,Math.min(r.bottom,innerHeight)-Math.max(r.top,0));if(a/(r.width*r.height)>.3)h.classList.add('visible')})}function panTo(side){let p=$('#pan');p.scrollTo({left:side==='left'?0:p.scrollWidth-p.clientWidth,behavior:'smooth'})}function bag(){return`<button class="bag-slot ${state.keyTaken?'used':''}" ${state.keyTaken?'':'disabled'}>${state.keyTaken?'⌕<small>置物櫃鑰匙・已使用</small>':''}</button><span class="bag-slot"></span><span class="bag-slot"></span><span class="bag-slot"></span>`}
function modal(html){keepPan();$('#modal')?.remove();let e=document.createElement('section');e.className='modal';e.id='modal';e.innerHTML=`<div class="panel">${html}</div>`;app.append(e)}function closeModal(){$('#modal')?.remove()}
function journal(){modal(`<button class="close" onclick="closeModal()">×</button><div class="journal"><div class="journal-title">班級日誌</div><h3>今日待確認事項</h3><ul class="checklist"><li>${state.socialControlCompleted?'☑':'□'} 課堂紀錄 ${!state.socialControlCompleted?'<button class="task-btn" onclick="controlGame()">課堂紀錄</button>':''}</li><li>${state.seatPlanCompleted?'☑':'□'} 座位表 ${state.seatPlanCompleted&&!state.socialNormsCompleted?'<button class="task-btn" onclick="normGame()">整理4張紀錄卡</button>':''}</li><li>${state.genderNormCompleted?'☑':'□'} 活動分工</li></ul>${state.socialControlCompleted&&!state.keyTaken?'<div class="note">講桌上有一把置物櫃鑰匙。</div>':''}${state.socialNormsCompleted&&!state.genderNormCompleted?'<div class="note">還有一項確認沒有完成。<br>班級活動的分工表貼在公告欄上。</div>':''}${state.genderNormCompleted&&!state.checkoutCompleted?'<button class="btn" onclick="checkout()">完成離班確認</button>':''}${state.checkoutCompleted?'<div class="journal-stamp">確認完成</div>':''}</div>`)}
function sort(type){selectedCard=null;let q=type==='socialNorms'?shuffle(LEVEL1_QUESTIONS.socialNorms):LEVEL1_QUESTIONS.socialControl,z=type==='socialNorms'?[['custom','風俗習慣'],['ethics','倫理道德'],['religion','宗教信仰'],['law','法律']]:[['inner','內在控制'],['formal','外在－正式控制'],['informal','外在－非正式控制']];modal(`<button class="close" onclick="journal()">×</button><h2>${type==='socialNorms'?'整理4張紀錄卡':'整理班級日誌中的課堂紀錄'}</h2><div class="cards">${q.map(x=>`<button class="card" data-card="${x.id}" onclick="pick('${x.id}')">${esc(x.text)}</button>`).join('')}</div><div class="zones">${z.map(x=>`<button class="zone" onclick="place('${x[0]}','${type}')">${x[1]}</button>`).join('')}</div><div class="feedback" id="feedback"></div>`)}function controlGame(){sort('socialControl')}function normGame(){sort('socialNorms')}function pick(id){selectedCard=id;document.querySelectorAll('.card').forEach(x=>x.classList.toggle('selected',x.dataset.card===id))}function place(zone,type){if(!selectedCard)return;let q=LEVEL1_QUESTIONS[type].find(x=>x.id===selectedCard);if(q.correctAnswer!==zone){$('#feedback').textContent=q.hint;selectedCard=null;return}let c=$(`[data-card="${selectedCard}"]`);c.disabled=true;c.classList.add('placed');selectedCard=null;if([...document.querySelectorAll('.card')].every(x=>x.disabled))setTimeout(()=>doneSort(type),200)}function doneSort(type){state[type==='socialControl'?'socialControlCompleted':'socialNormsCompleted']=true;save();keepPan();$('#modal')?.remove();renderScene();journal()}
function takeKey(){state.keyTaken=true;save();scene();toast('取得置物櫃鑰匙。')}function openLocker(){if(!state.keyTaken)return toast('置物櫃鎖著。');state.lockerOpened=true;save();scene();toast('喀。置物櫃打開了。')}
function seatGame(){placed={};selectedName=null;modal(`<button class="close" onclick="closeModal()">×</button><h2>整理203座位表</h2><p>依照三條線索，把四張姓名卡放回正確位置。</p><div class="seat-plan-ui"><div class="board-head">203座位表</div><div class="seat-directions"><span>左側｜靠走道</span><span>右側｜靠窗</span></div><div class="puzzle-grid">${seats.map((s,i)=>`<button class="seat" data-seat="${s}" onclick="put('${s}')"><small>${i<2?'第一排':'第二排'}</small><b>空白</b></button>`).join('')}</div></div><section class="seat-clues"><ol><li>子晴坐在靠走道的第一排。</li><li>柏翰坐在子晴後面。</li><li>宥辰坐在品妤前面。</li></ol></section><div class="name-row">${Object.values(answer).map(n=>`<button class="name-card" onclick="selectedName='${n}'">${n}</button>`).join('')}</div><button class="btn" id="confirmSeat" disabled onclick="checkSeat()">確認座位表</button><div id="feedback" class="feedback"></div>`)}function put(s){if(!selectedName)return;placed[s]=selectedName;$(`[data-seat="${s}"]`).innerHTML=`<small>${s==='A'||s==='B'?'第一排':'第二排'}</small><b>${selectedName}</b>`;selectedName=null;$('#confirmSeat').disabled=Object.keys(placed).length!==4}function checkSeat(){if(seats.every(s=>placed[s]===answer[s])){state.seatPlanCompleted=true;save();closeModal();scene();toast('座位表整理好了。班級日誌好像還有事情沒完成。')}else $('#feedback').textContent='好像還有人的位置不對。'}
function bulletin(){if(!state.socialNormsCompleted)return toast('普通的班級公告欄。');modal(`<button class="close" onclick="closeModal()">×</button><h2>公告欄</h2><p class="bulletin-instruction">203班級活動分工表貼在這裡。</p><div class="bulletin-closeup"><button class="activity-sheet-hit" onclick="genderGame()" aria-label="203班級活動分工表"></button>${anchor('activity','活動分工表')}</div>`)}function genderGame(){selectedGender=new Set();modal(`<button class="close" onclick="bulletin()">×</button><h2>班級活動分工表</h2><p>哪些分工，是先從「性別」推測一個人的能力或特質？</p><div class="notes">${LEVEL1_QUESTIONS.genderNorms.map(x=>`<button class="note-card" data-g="${x.id}" onclick="gender('${x.id}')">${esc(x.text)}</button>`).join('')}</div><div class="feedback" id="feedback"></div><button class="btn" onclick="checkGender()">確認選取</button>`)}function gender(id){selectedGender.has(id)?selectedGender.delete(id):selectedGender.add(id);$(`[data-g="${id}"]`).classList.toggle('selected',selectedGender.has(id))}function checkGender(){if([...selectedGender].sort().join()==='gender-a,gender-b')assignmentGame();else $('#feedback').textContent='再想想：是否先從性別推測一個人的能力或特質？'}function assignmentGame(){assignmentPlaced={};selectedAssignment=null;let cards=shuffle(['體力＋意願','能力／興趣＋意願','男生','女生']);modal(`<button class="close" onclick="bulletin()">×</button><h2>修改活動分工</h2><div class="assignment-match"><button class="assignment-slot" data-slot="carry" onclick="assign('carry')">搬運 → <b>空白</b></button><button class="assignment-slot" data-slot="decorate" onclick="assign('decorate')">布置 → <b>空白</b></button></div><div class="assignment-cards">${cards.map(x=>`<button class="assignment-card" onclick="selectedAssignment='${x}'">${x}</button>`).join('')}</div><button class="btn" onclick="finishGender()">完成修改</button><div class="feedback" id="feedback"></div>`)}function assign(id){if(!selectedAssignment)return;assignmentPlaced[id]=selectedAssignment;$(`[data-slot="${id}"]`).innerHTML=`${id==='carry'?'搬運':'布置'} → <b>${selectedAssignment}</b>`;selectedAssignment=null}function finishGender(){if(assignmentPlaced.carry!=='體力＋意願'||assignmentPlaced.decorate!=='能力／興趣＋意願')return $('#feedback').textContent='好像還有一項分工仍然是從性別做推測。';state.genderNormCompleted=true;save();bulletin();toast('活動分工確認完成。回班級日誌完成離班確認吧。')}
function checkout(){state.checkoutCompleted=true;save();journal();setTimeout(()=>review(0),700)}function review(page){let cards=[`<h2>社會控制</h2><div class="review-tree"><b>社會控制</b><br>├─ 內在控制：個人將社會規範內化，形成自我約束。<br>└─ 外在控制：來自外界的約束。<br>&nbsp;&nbsp;&nbsp;├─ 正式控制：法律、校規等正式制度。<br>&nbsp;&nbsp;&nbsp;└─ 非正式控制：家人、同儕、輿論等人際互動。</div>`,`<h2>社會規範</h2><p><b>風俗習慣</b>＝長期形成的生活慣例<br><b>倫理道德</b>＝對善惡、是非與應然行為的期待<br><b>宗教信仰</b>＝源自宗教教義與信仰的規範<br><b>法律</b>＝由國家制定或認可，具有國家強制力</p><p class="legend">同一個行為可能同時受到不只一種社會規範影響；判斷題目時，要看主要的規範來源。</p>`,`<h2>性別規範</h2><p>社會可能依性別形成對角色、行為或特質的期待。判斷一個人的能力與分工，不應只從性別推測。</p><p>搬運 → 體力＋意願<br>布置 → 能力／興趣＋意願</p><p class="legend">性別規範可能隨時代與社會文化而改變。</p>`];modal(`<button class="close" onclick="journal()">×</button><div class="review-count">本關公民複習　${page+1} / 3</div>${cards[page]}<div class="review-nav">${page?`<button class="mini" onclick="review(${page-1})">上一張</button>`:'<span></span>'}${page===2?'<button class="btn" onclick="completePage()">完成複習</button>':`<button class="btn" onclick="review(${page+1})">下一張</button>`}</div>`)}function completePage(){app.innerHTML=`<section class="complete-page"><div><p>壹｜放學後的203</p><h1>確認完成。</h1><div class="concept-tags">社會規範　社會控制　性別規範</div><div class="fragment-mark">Ⅰ</div><p>取得<br><b>規則之印・碎片Ⅰ</b><br>1 / 6</p><button class="btn light" onclick="title()">完成第一關</button></div></section>`}
function door(){toast(state.checkoutCompleted?'離班確認已完成。':'今天好像還有事情沒確認完。')}function hint(){toast(!state.socialControlCompleted?'先查看講桌上的班級日誌。':!state.keyTaken?'看看講桌上的鑰匙。':!state.seatPlanCompleted?'滑到右側，找到置物櫃。':!state.socialNormsCompleted?'班級日誌好像還有事情沒完成。':!state.genderNormCompleted?'班級活動分工表貼在公告欄上。':'回班級日誌完成離班確認。')}function menu(){modal(`<button class="close" onclick="closeModal()">×</button><h2>選單</h2><button class="btn" onclick="notes()">公民筆記</button><p><button class="mini" onclick="restartAsk()">重新開始第一關</button></p>`)}function notes(){modal(`<button class="close" onclick="menu()">×</button><h2>公民筆記</h2><p>已完成的分類與概念，會在本關複習中整理。</p>`)}function restartAsk(){modal(`<button class="close" onclick="menu()">×</button><h2>重新開始第一關？</h2><button class="btn red" onclick="restart()">確認重新開始</button><button class="mini" onclick="menu()">取消</button>`)}function restart(){state={...fresh,selectedInventoryItem:null,keyUsed:false};save();closeModal();renderScene(true)}
state.selectedInventoryItem??=null;state.keyUsed??=false;
function bag(){if(!state.keyTaken)return`<span class="bag-slot"></span><span class="bag-slot"></span><span class="bag-slot"></span><span class="bag-slot"></span>`;return`<button class="bag-slot key-slot ${state.selectedInventoryItem==='lockerKey'?'selected':''} ${state.keyUsed?'used':''}" onclick="selectLockerKey()"><img src="assets/overlays/locker-key-icon.svg" alt="置物櫃鑰匙"><small>${state.selectedInventoryItem==='lockerKey'?'已選取':state.keyUsed?'已使用':'置物櫃鑰匙'}</small></button><span class="bag-slot"></span><span class="bag-slot"></span><span class="bag-slot"></span>`}
function takeKey(){state.keyTaken=true;state.keyUsed=false;state.selectedInventoryItem=null;save();scene();toast('取得置物櫃鑰匙。')}
function selectLockerKey(){if(state.keyUsed)return toast('這把鑰匙已使用。');state.selectedInventoryItem=state.selectedInventoryItem==='lockerKey'?null:'lockerKey';save();scene();toast(state.selectedInventoryItem?'已選取置物櫃鑰匙。':'已取消選取。')}
function openLocker(){if(!state.keyTaken||state.selectedInventoryItem!=='lockerKey')return toast('置物櫃鎖住了。好像需要鑰匙。');state.lockerOpened=true;state.keyUsed=true;state.selectedInventoryItem=null;save();scene();toast('喀。置物櫃打開了。')}
function sort(type){selectedCard=null;let q=type==='socialNorms'?shuffle(LEVEL1_QUESTIONS.socialNorms):LEVEL1_QUESTIONS.socialControl,z=type==='socialNorms'?shuffle([['custom','風俗習慣'],['ethics','倫理道德'],['religion','宗教信仰'],['law','法律']]):[['inner','內在控制'],['formal','外在－正式控制'],['informal','外在－非正式控制']];modal(`<button class="close" onclick="journal()">×</button><h2>${type==='socialNorms'?'整理4張紀錄卡':'整理班級日誌中的課堂紀錄'}</h2><div class="cards">${q.map(x=>`<button class="card" data-card="${x.id}" onclick="pick('${x.id}')">${esc(x.text)}</button>`).join('')}</div><div class="zones">${z.map(x=>`<button class="zone" onclick="place('${x[0]}','${type}')">${x[1]}</button>`).join('')}</div><div class="feedback" id="feedback"></div>`)}
function doneSort(type){state[type==='socialControl'?'socialControlCompleted':'socialNormsCompleted']=true;save();keepPan();$('#modal')?.remove();renderScene();if(type==='socialControl')journal();else toast('4張紀錄卡整理完成。回班級日誌看看吧。')}
function bulletin(){if(!state.socialNormsCompleted)return toast('普通的班級公告欄。');modal(`<button class="close" onclick="closeModal()">×</button><h2>公告欄</h2><p class="bulletin-instruction">203班級活動分工表貼在這裡。</p><div class="bulletin-closeup"><button class="activity-sheet-hit" onclick="genderGame()" aria-label="203班級活動分工表"></button><button class="task-hint anchor-activity visible" onclick="genderGame()"><i></i>班級活動分工表</button></div>`)}
function review(page){let cards=[`<h2>社會控制</h2><div class="review-tree"><b>社會控制</b><br>├─ 內在控制：個人將社會規範內化，形成自我約束。<br>└─ 外在控制：來自外界的約束。<br>&nbsp;&nbsp;&nbsp;├─ 正式控制：法律、校規等正式制度。<br>&nbsp;&nbsp;&nbsp;└─ 非正式控制：習慣、道德、人際互動等。</div>`,`<h2>社會規範</h2><p><b>風俗習慣</b>＝長期形成的生活慣例<br><b>倫理道德</b>＝對善惡、是非與應然行為的期待<br><b>宗教信仰</b>＝源自宗教教義與信仰的規範<br><b>法律</b>＝由國家制定或認可，具有國家強制力</p><p class="legend">同一個行為可能同時受到不只一種社會規範影響；判斷題目時，要看主要的規範來源。</p>`,`<h2>性別規範</h2><p>社會可能依性別形成對角色、行為或特質的期待；這些期待可能隨時代與社會文化改變。</p><p><b>性別刻板印象</b><br>對特定性別形成固定、概括化的想像。例如認為「女生比較細心」、「男生比較勇敢」。</p><p><b>性別偏見</b><br>因性別刻板印象，而對特定性別產生先入為主的評價或態度。</p><p><b>性別歧視</b><br>因性別而給予不合理的差別待遇，使特定性別受到不利對待。</p><p><b>性別主流化</b><br>在政策、制度與各項決策中，將不同性別的處境、需求與可能影響納入考量，以促進性別平等。</p><p class="legend">性別規範可能隨時代與社會文化改變。</p>`];modal(`<button class="close" onclick="journal()">×</button><div class="review-count">本關公民複習　${page+1} / 3</div>${cards[page]}<div class="review-nav">${page?`<button class="mini" onclick="review(${page-1})">上一張</button>`:'<span></span>'}${page===2?'<button class="btn" onclick="completePage()">完成複習</button>':`<button class="btn" onclick="review(${page+1})">下一張</button>`}</div>`)}
start();

// 任務完成後保留目前的水平探索位置，短暫呈現成功訊息再回到教室。
function finishTask(message){keepPan();setTimeout(()=>{closeModal();renderScene();toast(`✓ ${message}`)},950)}
function doneSort(type){state[type==='socialControl'?'socialControlCompleted':'socialNormsCompleted']=true;save();const message=type==='socialControl'?'課堂紀錄整理完成。回班級日誌看看吧。':'4張紀錄卡整理完成。回班級日誌看看吧。';const feedback=$('#feedback');if(feedback)feedback.textContent='整理完成。';finishTask(message)}
function checkSeat(){if(seats.every(s=>placed[s]===answer[s])){state.seatPlanCompleted=true;save();const feedback=$('#feedback');if(feedback)feedback.textContent='座位表整理完成。';finishTask('座位表整理好了。班級日誌好像還有事情沒完成。')}else $('#feedback').textContent='好像還有人的位置不對。'}
function finishGender(){const hasGenderChoice=['男生','女生'].some(x=>assignmentPlaced.carry===x||assignmentPlaced.decorate===x);if(hasGenderChoice){$('#feedback').textContent='這項分工仍然先用「性別」推測一個人的能力或特質，再想想看。';return}if(assignmentPlaced.carry!=='體力＋意願'||assignmentPlaced.decorate!=='能力／興趣＋意願'){$('#feedback').textContent='已經沒有用性別來分工了！再想想看：哪一項條件和這個任務本身更有關？';return}state.genderNormCompleted=true;save();const feedback=$('#feedback');if(feedback)feedback.textContent='活動分工確認完成。';finishTask('活動分工確認完成。回班級日誌看看吧。')}
